const findings = $('Count Unknown Calls').first().json;
const total = findings.total_unknown || 0;
const errors = findings.errors || 0;
const models = Array.isArray(findings.models) ? findings.models.filter(Boolean) : [];
const projects = Array.isArray(findings.project_ids) ? findings.project_ids.filter(Boolean) : [];
const firstAt = findings.first_at ? new Date(findings.first_at).toISOString() : '?';
const lastAt = findings.last_at ? new Date(findings.last_at).toISOString() : '?';

const subject = '[ALERTA] ' + total + ' llamadas LLM con agent_name=unknown_agent en 24h';

const lines = [];
lines.push('Se detectaron llamadas a util_llm_call sin agent_name correcto en las ultimas 24h.');
lines.push('');
lines.push('Cuando un agente no envia agent_name en el payload, util_llm_call cae al default unknown_agent. Eso significa que algun agente esta llamando al LLM sin identificarse, y los costes/metricas no se imputan correctamente.');
lines.push('');
lines.push('DETALLES:');
lines.push('- Total llamadas afectadas: ' + total);
lines.push('- De las cuales con error: ' + errors);
lines.push('- Modelos invocados: ' + (models.length ? models.join(', ') : '(ninguno conocido)'));
lines.push('- Proyectos afectados: ' + (projects.length ? projects.length + ' (' + projects.slice(0,3).join(', ') + (projects.length > 3 ? ', ...' : '') + ')' : 'ninguno (project_id NULL)'));
lines.push('- Primera ocurrencia: ' + firstAt);
lines.push('- Ultima ocurrencia: ' + lastAt);
lines.push('');
lines.push('ACCION RECOMENDADA:');
lines.push('1. Buscar en n8n el agente que recientemente fue modificado o creado.');
lines.push('2. Inspeccionar su nodo de Build/Prepare LLM Payload.');
lines.push('3. Confirmar que el return incluya: agent_name: \'agent_xxx\' (literal hardcoded).');
lines.push('4. Patron correcto, ejemplo de agent_briefing:');
lines.push('   return [{ json: { agent_name: \'agent_briefing\', project_id: ..., prompt_system: ..., prompt_user: ..., model: ..., temperature: ... } }];');
lines.push('');
lines.push('Query de diagnostico (Supabase):');
lines.push('  SELECT agent_name, count(*), max(occurred_at)');
lines.push('  FROM llm_calls');
lines.push('  WHERE occurred_at > now() - INTERVAL \'24 hours\'');
lines.push('    AND agent_name IN (\'unknown_agent\', \'unknown\', \'\')');
lines.push('  GROUP BY agent_name;');
lines.push('');
lines.push('Audit de referencia: studio-multiagente/docs/fase_a_audit.md (seccion A2).');

return [{ json: {
  subject,
  body: lines.join('\n'),
  total_unknown: total,
  errors,
  models,
  projects
}}];
